from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r,c) in seen:
                continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==color:
                        seen.add((ny,nx)); q.append((ny,nx))
            if len(cells)>=2:
                ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
                boxes.append((color,min(ys),max(ys),min(xs),max(xs)))
    out=[[bg]*w for _ in range(h)]
    for color,r0,r1,c0,c1 in boxes:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1): out[r][c]=color
    return out

